class DTvsUE(object):

    _instance = None
    _ue_store = {}

    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            cls._instance = super(DTvsUE, cls).__new__(cls, *args, **kwargs)
        return cls._instance

    def init_store(self):
        self._ue_store = {}

    def get_ue(self, dt_name):
        ue = self._ue_store.get(dt_name, None)
        if ue:
            return ue
        else:
            raise KeyError("dt_name: {} not in DTvsUE pool".format(dt_name))

    def store_ue(self, dt_name, ue):
        self._ue_store[dt_name] = ue


class DTvsLOG(object):

    _instance = None
    _dt_store = {}

    def __new__(cls, *args, **kwargs):
        if not cls._instance:
            cls._instance = super(DTvsLOG, cls).__new__(cls, *args, **kwargs)
        return cls._instance

    def init_store(self):
        self._dt_store = {}

    def get_log(self, dt_name):
        return self._dt_store.get(dt_name, None)

    def store_log(self, dt_name, log_path, omit, end):
        log_details = {"log_path": log_path, "omit": omit, "end": end}
        self._dt_store[dt_name] = log_details
